import React, { useEffect, useState } from "react";
import {
  Card,
  CardHeader,
  CardContent,
  CardActions,
  Avatar,
  Typography,
  IconButton,
  Grid,
  Box,
  Button,
  TextField,
} from "@mui/material";
import { Favorite, ChatBubbleOutline } from "@mui/icons-material";

export default function Feed() {
  const [posts, setPosts] = useState([]);
  const [text, setText] = useState("");

  // Fetch posts
  useEffect(() => {
    fetch("http://localhost:5000/api/posts")
      .then((res) => res.json())
      .then(setPosts)
      .catch(console.error);
  }, []);

  // Create post
  const handlePost = async () => {
    if (!text.trim()) return;
    const res = await fetch("http://localhost:5000/api/posts", {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ text }),
    });
    if (res.ok) {
      const newPost = await res.json();
      setPosts([newPost, ...posts]);
      setText("");
    }
  };

  return (
    <Box sx={{ mt: 4 }}>
      <Typography variant="h5" sx={{ mb: 2 }}>
        Create a Post
      </Typography>
      <Box sx={{ display: "flex", gap: 2, mb: 4 }}>
        <TextField
          label="What's on your mind?"
          variant="outlined"
          value={text}
          onChange={(e) => setText(e.target.value)}
          fullWidth
        />
        <Button variant="contained" color="primary" onClick={handlePost}>
          Post
        </Button>
      </Box>

      <Grid container spacing={3}>
        {posts.map((p) => (
          <Grid item xs={12} md={6} lg={4} key={p._id}>
            <Card sx={{ boxShadow: 3 }}>
              <CardHeader
                avatar={<Avatar>{p.user?.[0]?.toUpperCase()}</Avatar>}
                title={p.user || "Anonymous"}
                subheader={new Date(p.createdAt).toLocaleString()}
              />
              {p.image && (
                <Box
                  component="img"
                  src={p.image}
                  alt="post"
                  sx={{
                    width: "100%",
                    maxHeight: 300,
                    objectFit: "cover",
                  }}
                />
              )}
              <CardContent>
                <Typography>{p.text}</Typography>
              </CardContent>
              <CardActions disableSpacing>
                <IconButton>
                  <Favorite />
                </IconButton>
                <IconButton>
                  <ChatBubbleOutline />
                </IconButton>
              </CardActions>
            </Card>
          </Grid>
        ))}
      </Grid>
    </Box>
  );
}
